#{item,jdbcType=VARCHAR}
#{submitFeedbackStatus,jdbcType=VARCHAR}
AND to_char(cds.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') >= #{submitDeadLineStart,jdbcType=VARCHAR}
AND to_char(cds.CHB_SUBMIT_DEADLINE,'yyyy-MM-dd') <= #{submitDeadLineEnd,jdbcType=VARCHAR}
and to_char(cds.RAISE_PSTRDATE,'yyyy-MM-dd') >= #{raise_startdateStart,jdbcType=VARCHAR}
and to_char(cds.RAISE_PSTRDATE,'yyyy-MM-dd') <= #{raise_startdateEnd,jdbcType=VARCHAR}
and to_char(cds.STATUS_DATE,'yyyy-MM-dd') >= #{statusDateStart,jdbcType=VARCHAR}
and to_char(cds.STATUS_DATE,'yyyy-MM-dd') <= #{statusDateEnd,jdbcType=VARCHAR}
and to_char(cds.SUBMIT_TIME,'yyyy-MM-dd') >= #{submitDateStart,jdbcType=VARCHAR}
and to_char(cds.SUBMIT_TIME,'yyyy-MM-dd') <= #{submitDateEnd,jdbcType=VARCHAR}
/* and cds.PROD_NAME like '%${prodName}%' */ and cds.PROD_NAME like concat('%', concat(#{prodName},'%'))
and cds.PROD_ID = #{prodId}
and cds.SEND_STATUS = #{sendStatus}
